using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
using System.IO;

namespace LabWinForms;
internal static class Program { [STAThread] static void Main() { Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false); Application.Run(new MainForm()); } }
public class MainForm : Form {
 public MainForm() { Text="BÀI THỰC HÀNH LAB"; Width=760;Height=600; var panel=new FlowLayoutPanel {Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,AutoScroll=true,Padding=new Padding(20)};Controls.Add(panel);
 var b0=new Button {Text="Bài tập tại lớp - Bài 1: Ước số",Width=660,Height=42}; b0.Click+=(s,e)=>new Exercise1().Show();panel.Controls.Add(b0);
 var b1=new Button {Text="Bài tập tại lớp - Bài 2: Quản lý sinh viên TreeView",Width=660,Height=42}; b1.Click+=(s,e)=>new Exercise2().Show();panel.Controls.Add(b1);
 var b2=new Button {Text="Bài tập nâng cao - Bài 1: Xử lý chuỗi",Width=660,Height=42}; b2.Click+=(s,e)=>new Exercise3().Show();panel.Controls.Add(b2);
 var b3=new Button {Text="Bài tập về nhà - Bài 1: Từ điển",Width=660,Height=42}; b3.Click+=(s,e)=>new Exercise4().Show();panel.Controls.Add(b3);
 var b4=new Button {Text="Bài tập về nhà - Bài 2: Xử lý ListBox",Width=660,Height=42}; b4.Click+=(s,e)=>new Exercise5().Show();panel.Controls.Add(b4);
 var b5=new Button {Text="Bài tập về nhà - Bài 3: Danh bạ",Width=660,Height=42}; b5.Click+=(s,e)=>new Exercise6().Show();panel.Controls.Add(b5);
 } }

public abstract class BaseExercise : Form { protected FlowLayoutPanel Panel; protected BaseExercise(string title) { Text=title;Width=900;Height=650;StartPosition=FormStartPosition.CenterScreen;Panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,AutoScroll=true,Padding=new Padding(18),WrapContents=false};Controls.Add(Panel); } protected TextBox Field(string label) {var row=new FlowLayoutPanel{Width=800,Height=38};row.Controls.Add(new Label{Text=label,Width=140,TextAlign=ContentAlignment.MiddleLeft});var t=new TextBox{Width=420};row.Controls.Add(t);Panel.Controls.Add(row);return t;} protected Button Action(string title,Action handler){var b=new Button{Text=title,Width=190,Height=36};b.Click+=(s,e)=>{try{handler();}catch(Exception ex){MessageBox.Show(ex.Message);}};Panel.Controls.Add(b);return b;} protected void Warn(string message)=>MessageBox.Show(message,"Thông báo");protected bool Confirm()=>MessageBox.Show("Bạn có chắc chắn?","Xác nhận",MessageBoxButtons.YesNo)==DialogResult.Yes; }

public class Exercise1:BaseExercise {public Exercise1():base("ƯỚC SỐ"){var t=Field("Nhập số nguyên dương");var combo=new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList};Panel.Controls.Add(combo);var list=new ListBox{Width=350,Height=210};Panel.Controls.Add(list);Action("Cập nhật",()=>{if(!int.TryParse(t.Text,out int n)||n<=0)throw new Exception("Nhập số nguyên dương hợp lệ");if(combo.Items.Contains(n))throw new Exception("Số đã tồn tại");combo.Items.Add(n);combo.SelectedItem=n;t.Clear();t.Focus();});combo.SelectedIndexChanged+=(s,e)=>{list.Items.Clear();int n=(int)combo.SelectedItem!;for(int i=1;i<=n;i++)if(n%i==0)list.Items.Add(i);};Action("Tổng các ước số",()=>Warn(list.Items.Cast<int>().Sum().ToString()));Action("Số ước chẵn",()=>Warn(list.Items.Cast<int>().Count(x=>x%2==0).ToString()));Action("Số ước nguyên tố",()=>Warn(list.Items.Cast<int>().Count(x=>x>1&&Enumerable.Range(2,Math.Max(0,(int)Math.Sqrt(x)-1)).All(d=>x%d!=0)).ToString()));Action("Thoát",()=>{if(Confirm())Close();});}}
public class Exercise2:BaseExercise {public Exercise2():base("QUẢN LÝ SINH VIÊN"){var tree=new TreeView{Width=420,Height=220};Panel.Controls.Add(tree);var root=tree.Nodes.Add("Danh sách lớp");var combo=new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList};Panel.Controls.Add(combo);foreach(var name in new[]{"05DHTH1","05DHTH2","05DHTH3","05DHTH4"}){root.Nodes.Add(name);combo.Items.Add(name);}combo.SelectedIndex=0;root.Expand();var ck=new CheckBox{Text="Thêm lớp"};Panel.Controls.Add(ck);var group=new GroupBox{Text="Thông tin lớp",Width=500,Height=65,Visible=false};var className=new TextBox{Width=230,Left=12,Top=25};var addClass=new Button{Text="Thêm lớp",Left=260,Top=23};group.Controls.AddRange(new Control[]{className,addClass});Panel.Controls.Add(group);ck.CheckedChanged+=(s,e)=>group.Visible=ck.Checked;addClass.Click+=(s,e)=>{string n=className.Text.Trim();if(n.Length==0||combo.Items.Contains(n)){Warn("Tên lớp rỗng hoặc trùng");return;}root.Nodes.Add(n);combo.Items.Add(n);className.Clear();};var id=Field("Mã sinh viên");var nameField=Field("Họ tên");var address=Field("Địa chỉ");Action("Cập nhật",()=>{if(new[]{id.Text,nameField.Text,address.Text}.Any(string.IsNullOrWhiteSpace))throw new Exception("Nhập đủ thông tin");foreach(TreeNode cls in root.Nodes)foreach(TreeNode st in cls.Nodes)if(st.Tag is Student x&&x.Id==id.Text.Trim())throw new Exception("Trùng mã sinh viên");TreeNode target=root.Nodes.Cast<TreeNode>().First(x=>x.Text==combo.Text);target.Nodes.Add(new TreeNode(id.Text+", "+nameField.Text){Tag=new Student(id.Text,nameField.Text,address.Text)});target.Expand();});Action("Xóa sinh viên",()=>{if(tree.SelectedNode?.Tag is not Student)throw new Exception("Chọn node sinh viên");if(Confirm())tree.SelectedNode.Remove();});tree.AfterSelect+=(s,e)=>{if(e.Node.Tag is Student x){id.Text=x.Id;nameField.Text=x.Name;address.Text=x.Address;combo.SelectedItem=e.Node.Parent.Text;}};}record Student(string Id,string Name,string Address);}
public class Exercise3:BaseExercise {public Exercise3():base("XỬ LÝ CHUỖI"){var list=new ListBox{Width=430,Height=270,SelectionMode=SelectionMode.MultiExtended};Panel.Controls.Add(list);string[] ho={"Lê","Nguyễn","Lý","Trần","Lâm","Hồ","Lai","Huỳnh","La"},lot={"Quang","Thành","Ngọc","Anh","Xuân","Bảo","Cẩm","Thị","Kim","Thái","Hồng"},ten={"Hà","Danh","Sơn","Mai","Thắng","Kỳ","Thành","Lâm","Tâm","Phụng","Thắm"};var rng=new Random();Action("Nhập tên ngẫu nhiên",()=>{for(int i=0;i<50;i++)list.Items.Add($"{ho[rng.Next(ho.Length)]} {lot[rng.Next(lot.Length)]} {ten[rng.Next(ten.Length)]}");});Action("Xóa phần tử đang chọn",()=>{foreach(var x in list.SelectedItems.Cast<object>().ToArray())list.Items.Remove(x);});Action("Xóa tên có tên là Sơn",()=>{foreach(var x in list.Items.Cast<string>().Where(x=>x.EndsWith(" Sơn")).ToArray())list.Items.Remove(x);});Action("Xóa tên có họ là Lê",()=>{foreach(var x in list.Items.Cast<string>().Where(x=>x.StartsWith("Lê ")).ToArray())list.Items.Remove(x);});Action("Chuyển thành chữ HOA",()=>Change(x=>x.ToUpperInvariant()));Action("Chuyển thành chữ thường",()=>Change(x=>x.ToLowerInvariant()));Action("Viết hoa đầu mỗi từ",()=>Change(x=>System.Globalization.CultureInfo.GetCultureInfo("vi-VN").TextInfo.ToTitleCase(x.ToLowerInvariant())));Action("Xóa tất cả",()=>list.Items.Clear());void Change(Func<string,string> f){foreach(int i in list.SelectedIndices.Cast<int>().ToArray())list.Items[i]=f(list.Items[i]!.ToString()!);}list.DoubleClick+=(s,e)=>{if(list.SelectedIndex<0)return;int i=list.SelectedIndex;string old=list.Items[i]!.ToString()!;string? value=Microsoft.VisualBasic.Interaction.InputBox("Nhập tên mới","Sửa tên",old);if(!string.IsNullOrWhiteSpace(value))list.Items[i]=value.Trim();};}}
public class Exercise4:BaseExercise {public Exercise4():base("TỪ ĐIỂN ANH - VIỆT / VIỆT - ANH"){var words=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"student","sinh viên"},{"teacher","giáo viên"},{"worker","công nhân"},{"hat","mũ"},{"head","đầu"},{"mouse","chuột"},{"cat","mèo"},{"dog","chó"},{"snake","rắn"},{"frog","ếch"},{"sheep","cừu"}};var tabs=new TabControl{Width=680,Height=420};Panel.Controls.Add(tabs);foreach(bool reverse in new[]{false,true}){var page=new TabPage(reverse?"VIỆT - ANH":"ANH - VIỆT");tabs.TabPages.Add(page);var combo=new ComboBox{Left=20,Top=30,Width=260,AutoCompleteMode=AutoCompleteMode.SuggestAppend,AutoCompleteSource=AutoCompleteSource.ListItems};var result=new TextBox{Left=300,Top=30,Width=290,Height=240,Multiline=true,ReadOnly=true};page.Controls.AddRange(new Control[]{combo,result});foreach(var kv in words)combo.Items.Add(reverse?kv.Value:kv.Key);var button=new Button{Text="Tra cứu (Enter)",Left=20,Top=75,Width=250};page.Controls.Add(button);void Search(){string key=combo.Text.Trim();var hit=words.FirstOrDefault(x=>string.Equals(reverse?x.Value:x.Key,key,StringComparison.OrdinalIgnoreCase));result.Text=hit.Key==null?"Không tìm thấy":reverse?hit.Key:hit.Value;}button.Click+=(s,e)=>Search();combo.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){Search();e.SuppressKeyPress=true;}};combo.DoubleClick+=(s,e)=>Search();}Action("Thoát",Close);}}
public class Exercise5:BaseExercise {public Exercise5():base("XỬ LÝ LISTBOX"){var t=Field("Nhập số tự nhiên");var list=new ListBox{Width=380,Height=230,SelectionMode=SelectionMode.MultiExtended};Panel.Controls.Add(list);Action("Nhập",()=>{if(!long.TryParse(t.Text,out long n)||n<0)throw new Exception("Nhập số tự nhiên hợp lệ");list.Items.Add(n);t.Clear();});Action("Tổng các phần tử",()=>Warn(list.Items.Cast<long>().Sum().ToString()));Action("Xóa đầu và cuối",()=>{if(list.Items.Count>0)list.Items.RemoveAt(list.Items.Count-1);if(list.Items.Count>0)list.Items.RemoveAt(0);});Action("Xóa đang chọn",()=>{foreach(var x in list.SelectedItems.Cast<object>().ToArray())list.Items.Remove(x);});Action("Tăng mỗi phần tử 2",()=>{for(int i=0;i<list.Items.Count;i++)list.Items[i]=checked((long)list.Items[i]!+2);});Action("Bình phương",()=>{for(int i=0;i<list.Items.Count;i++){long x=(long)list.Items[i]!;list.Items[i]=checked(x*x);}});Action("Chọn số chẵn",()=>Select(0));Action("Chọn số lẻ",()=>Select(1));void Select(int mod){list.ClearSelected();for(int i=0;i<list.Items.Count;i++)if((long)list.Items[i]!%2==mod)list.SetSelected(i,true);}}}
public class Exercise6:BaseExercise {public Exercise6():base("DANH BẠ A - Z"){var tree=new TreeView{Width=450,Height=320};Panel.Controls.Add(tree);foreach(char c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ")tree.Nodes.Add(c.ToString());var first=Field("First Name (tên)");var last=Field("Last Name (họ)");Action("Add",()=>{string f=first.Text.Trim(),l=last.Text.Trim();if(f.Length==0||l.Length==0)throw new Exception("Nhập họ và tên");string initial=RemoveMarks(f).Substring(0,1).ToUpperInvariant();var node=tree.Nodes.Cast<TreeNode>().FirstOrDefault(x=>x.Text==initial);if(node==null)throw new Exception("Tên phải bắt đầu bằng A-Z");node.Nodes.Add(f+", "+l);node.Expand();first.Clear();last.Clear();});Action("Exit",Close);}static string RemoveMarks(string s){string n=s.Normalize(System.Text.NormalizationForm.FormD);return new string(n.Where(c=>System.Globalization.CharUnicodeInfo.GetUnicodeCategory(c)!=System.Globalization.UnicodeCategory.NonSpacingMark).ToArray()).Replace('Đ','D').Replace('đ','d');}}
